int Join(int first, int second) => first * 10 + second;
void Main() {
    var total = 0;
    for (var i = 0; i < 4; i++) { if (i == 1) continue; total += i; }
    Print(total);
    var n = 0;
    Print(Join(second: n++, first: ++n)); Print(n);
    Print(false && n++ == 0); Print(n);
    Print(true || ++n == 0); Print(n);
    Print(false ? n++ : ++n); Print(n);
    do { total--; } while (total > 2);
    Print(total);
    while (--n > 0) ;
    Print(n);
}
